import assert from 'node:assert/strict';
import { slugify } from '../src/slugify.js';

const mode = process.argv[2];
const check = (input, expected) => assert.equal(slugify(input), expected, JSON.stringify(input));

if (mode === 'canonical') {
  for (const [input, expected] of [
    ['Crème Brûlée', 'creme-brulee'],
    ['Łódź', 'lodz'],
    ['  déjà vu! São Tomé & Príncipe  ', 'deja-vu-sao-tome-principe'],
    ['Cafe\u0301 noir', 'cafe-noir'],
    ['a\u0308\u0304b e\u0301\u0323clair', 'ab-eclair'],
    ['İSTANBUL', 'istanbul'],
    ['Việt Nam 2025', 'viet-nam-2025'],
  ]) check(input, expected);
  let count = 0;
  for (let cp = 0; cp <= 0x10ffff; cp++) {
    const letter = String.fromCodePoint(cp);
    if (!/^\p{L}$/u.test(letter) || !/^\p{Script=Latin}$/u.test(letter)) continue;
    const decomposed = letter.normalize('NFD');
    const ascii = decomposed.replace(/\p{M}/gu, '').toLowerCase();
    if (!/^[a-z]+$/.test(ascii)) continue;
    check(`x${letter}z`, `x${ascii}z`);
    check(`x${decomposed}z`, `x${ascii}z`);
    count++;
  }
  assert.ok(count > 400, 'coverage includes Latin extended diacritics');
} else if (mode === 'special') {
  const groups = [
    ['Ææ', 'ae'], ['Œœ', 'oe'], ['ßẞ', 'ss'],
    ['Øø', 'o'], ['Łł', 'l'], ['Đđ', 'd'], ['Ðð', 'd'],
    ['Þþ', 'th'], ['Ħħ', 'h'], ['Ŧŧ', 't'], ['Ŋŋ', 'n'],
    ['ı', 'i'], ['ſ', 's'],
  ];
  for (const [letters, ascii] of groups) {
    for (const letter of letters) {
      check(letter, ascii);
      check(`A${letter}B`, `a${ascii}b`);
      check(`A${letter}\u0301\u0323B`, `a${ascii}b`);
    }
  }
  check('Æsir & Œuvre — Straße, smørrebrød', 'aesir-oeuvre-strasse-smorrebrod');
  check('Þingvellir, Đorđe, ħ', 'thingvellir-dorde-h');
  check('ﬀ ﬁ ﬂ ﬃ ﬄ ﬅ ﬆ', 'ff-fi-fl-ffi-ffl-st-st');
} else if (mode === 'preserve') {
  const oldSlug = title => title.toLowerCase().replace(/[^\p{L}\p{N}]+/gu, '-').replace(/^-+|-+$/g, '');
  for (const input of [
    '', 'Hello, World!', '  --Release 2.0--  ', 'ABC_xyz / 9.0',
    '0123456789 ١٢٣ １２３', 'a😀b👩‍💻c', 'a\u0000b', '---',
    'Привет мир', 'Йога ЁЖ Ї Є Ґ', 'Ελληνικά ΐ ΰ Ά Έ Ώ',
    '日本語 カタカナ ひらがな', '한글 안녕하세요', '你好 世界',
    'العربية فارسی', 'עברית', 'हिन्दी বাংলা', 'ไทย',
    'ᎠᎡᎢ ႠႡႢ ԱԲԳ',
  ]) check(input, oldSlug(input));
  // Preserve each non-Latin letter, including letters whose canonical decomposition
  // would change under blanket accent removal (Greek, Cyrillic, Hangul, etc.).
  for (let cp = 0; cp <= 0x10ffff; cp++) {
    const letter = String.fromCodePoint(cp);
    if (!/^\p{L}$/u.test(letter) || /^\p{Script=Latin}$/u.test(letter)) continue;
    check(letter, oldSlug(letter));
  }
} else {
  throw new Error(`Unknown mode: ${mode}`);
}
console.log(`${mode}: OK`);
